export const meta = {
  name: '@@WORKFLOW_NAME@@',
  description: '@@WORKFLOW_DESCRIPTION@@',
  phases: [
    {title: 'Probe', detail: 'one agent per /execution agent type proves its definition loaded and its guard fires'}
  ]
}

// /execution start-of-run probe, generated by `exec.py agents probe` from assets/workflows/probe.template.js.
// Contract: contract/AGENTS.md 5.3 and HOOKS.md 13.3. Plain JavaScript run by the Workflow tool, under the same
// constraints as a wave script (WAVES.md 2): the clock comes from args.now_utc, no randomness, no module loading and
// no host API. The evidence is read from files by `exec.py agents probe-check` (hook events, the forbidden files);
// this script only starts the five probe agents and returns what they answered.

const PROBE = /*@@PROBE@@*/null;

const ARGS = (typeof args === 'object' && args !== null) ? args : {};
const NOW_UTC = typeof ARGS.now_utc === 'string' ? ARGS.now_utc : PROBE.now_utc;

function promptFor(name) {
  const steps = [
    'Start-of-run probe of the /execution skill. This message is your whole task: there is no brief file, and the ' +
      'standing rules of your instructions still apply (in particular: never retry a refused call in another form).',
    'Do exactly these steps, in this order, and nothing else:',
    '1. Run this Bash command exactly: echo execution-probe ' + PROBE.bind_nonce + ' ' + name,
    '2. Use the Write tool to create the file ' + PROBE.forbidden[name] + ' with the text "probe". This write must ' +
      'be refused by a hook; when it is refused, note the refusal code (the text before the first colon of the ' +
      'reason) and do not try again in any other way.'
  ];
  if (name === PROBE.commit_agent) {
    steps.push('3. Run this Bash command exactly (it is the whole line after the colon): git commit --allow-empty -F ' +
      PROBE.commit_message_path);
    steps.push('   It must be refused by a hook; note the refusal code and do not try again in any other way.');
  }
  steps.push('Then return, through the StructuredOutput tool and nothing else, the object {name, marker, refused}: ' +
    'name = "' + name + '"; marker = the exact line of your own instructions that starts with ' +
    '"execution-agent-template:" (copy it character for character, or the empty string if your instructions have ' +
    'no such line); refused = the list of refusal codes you saw, in order (an empty list if nothing was refused).');
  return steps.join('\n');
}

async function probeOne(name) {
  const opts = {
    agentType: name,
    model: PROBE.model,
    effort: PROBE.effort,
    label: 'probe ' + name,
    phase: 'Probe',
    schema: PROBE.schema
  };
  try {
    const result = await agent(promptFor(name), opts);
    if (result === null || result === undefined) {
      log(name + ': the probe agent returned nothing (null); probe-check will fail this type');
      return {name, outcome: 'null', result: null, error: null};
    }
    return {name, outcome: 'returned', result, error: null};
  } catch (err) {
    const text = err && err.message ? err.message : String(err);
    log(name + ': the probe agent could not run: ' + text);
    return {name, outcome: 'threw', result: null, error: text};
  }
}

log('agents probe at ' + NOW_UTC + ': ' + PROBE.agents.join(' '));
const answers = await Promise.all(PROBE.agents.map((name) => probeOne(name)));
log('agents probe finished: ' + answers.map((a) => a.name + '=' + a.outcome).join(' '));
return {probe: PROBE.workflow_name, now_utc: NOW_UTC, agents: answers};
